# Amounts are integers in minor units (cents); UNIQUE(idem_key) on payments.
def create_payment(db, psp, key: str, order_id: str, amount: int, token: str) -> dict:
    with db.tx():
        found = db.one("SELECT id, state FROM payments WHERE idem_key = %s", key)
        if found:
            return found                      # client retry: same answer, no new charge
        pay = db.one("INSERT INTO payments (idem_key, order_id, amount, state) "
                     "VALUES (%s, %s, %s, 'PENDING') RETURNING id, state", key, order_id, amount)
    try:
        res = psp.charge(amount, token, idempotency_key=key)   # same key on every retry
    except TimeoutError:
        return pay                            # unknown, not failed: webhook or poll settles it
    return settle(db, pay["id"], res)

def settle(db, pay_id: int, res) -> dict:
    with db.tx():
        state = "SUCCEEDED" if res.ok else "FAILED"
        n = db.run("UPDATE payments SET state = %s WHERE id = %s AND state = 'PENDING'",
                   state, pay_id)
        if n == 1 and res.ok:                 # first writer wins: API reply or webhook
            commission = res.amount // 10     # assumed 10% marketplace take
            post(db, pay_id, [                # debits +, credits -
                ("psp_receivable", res.amount - res.fee),
                ("psp_fee_expense", res.fee),
                ("seller_payable", -(res.amount - commission)),
                ("platform_revenue", -commission),
            ])
    return db.one("SELECT id, state FROM payments WHERE id = %s", pay_id)

def post(db, pay_id: int, entries: list[tuple[str, int]]) -> None:
    assert sum(amount for _, amount in entries) == 0, "unbalanced journal entry"
    for account, amount in entries:
        db.run("INSERT INTO ledger_entries (payment_id, account, amount) "
               "VALUES (%s, %s, %s)", pay_id, account, amount)
